import java.util.Collections;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_getChildBefore_TriageGen1Test {



    @Test
    public void testGetChildBefore_MiddleChildReturnsPrevious() {
        Node parent = new Node(1);
        Node child1 = new Node(2);
        Node child2 = new Node(3);
        Node child3 = new Node(4);

        parent.addChildToBack(child1);
        parent.addChildToBack(child2);
        parent.addChildToBack(child3);

        // child2's predecessor is child1
        assertEquals("The child before child2 should be child1", child1, parent.getChildBefore(child2));
        // child3's predecessor is child2
        assertEquals("The child before child3 should be child2", child2, parent.getChildBefore(child3));
    }






}

