public class Node_getChildBefore_TriageGen1Test {







    @Test(expected = RuntimeException.class)
    public void testGetChildBefore_NodeIsNotAChildThrowsException() {
        Node parent = new Node(1);
        Node child1 = new Node(2);
        Node stranger = new Node(3);

        parent.addChildToBack(child1);

        // stranger is not in the parent's child list
        parent.getChildBefore(stranger);
    }


